#include "BeatMakerPanel.h"
#include <algorithm>
namespace ssbb {
BeatMakerPanel::BeatMakerPanel(BeatEngine&e):engine_(e){title_.setText("2. Beat Maker",juce::dontSendNotification);title_.setFont(juce::FontOptions(17.0f,juce::Font::bold));bpmLabel_.setText("BPM",juce::dontSendNotification);bpm_.setRange(50,220,1);bpm_.setValue(96);bpm_.setTextBoxStyle(juce::Slider::TextBoxLeft,false,48,22);preset_.addItem("West Coast Bounce",1);preset_.addItem("Boom Bap",2);preset_.setSelectedId(1);addAndMakeVisible(title_);addAndMakeVisible(bpmLabel_);addAndMakeVisible(bpm_);addAndMakeVisible(preset_);const char*n[]={"K","S","H"};for(int l=0;l<3;++l){labels_[l].setText(n[l],juce::dontSendNotification);addAndMakeVisible(labels_[l]);for(int s=0;s<16;++s){addAndMakeVisible(steps_[l][s]);steps_[l][s].onClick=[this,l,s]{engine_.setStep(l,s,steps_[l][s].getToggleState());};}}bpm_.onValueChange=[this]{engine_.setTempo(bpm_.getValue());};preset_.onChange=[this]{if(preset_.getSelectedId()==2)engine_.loadBoomBap();else engine_.loadWestCoastBounce();sync();};engine_.loadWestCoastBounce();sync();}
void BeatMakerPanel::sync(){for(int l=0;l<3;++l)for(int s=0;s<16;++s)steps_[l][s].setToggleState(engine_.getStep(l,s),juce::dontSendNotification);}void BeatMakerPanel::paint(juce::Graphics&g){g.setColour(juce::Colour(0xff1b2030));g.fillRoundedRectangle(getLocalBounds().toFloat(),8);}void BeatMakerPanel::resized(){auto r=getLocalBounds().reduced(10);title_.setBounds(r.removeFromTop(28));auto top=r.removeFromTop(34);preset_.setBounds(top.removeFromLeft(top.getWidth()/2).reduced(2));bpmLabel_.setBounds(top.removeFromLeft(36));bpm_.setBounds(top);const int label=24,cell=std::max(12,(r.getWidth()-label)/16);for(int l=0;l<3;++l){auto row=r.removeFromTop(38);labels_[l].setBounds(row.removeFromLeft(label));for(int s=0;s<16;++s)steps_[l][s].setBounds(row.removeFromLeft(cell).reduced(1));}}
} // namespace ssbb
